"""
Fast bounded dataframe column-permutation optimizer for serial LLM prefix caching.

The implementation preserves all rows, columns, indices, cell values, and
shape.  It creates a small bounded set of candidate per-row column orders and
selects the candidate with the best exact ideal character-Trie reuse score.

Candidates:
1. Global order ranked by length-weighted repeated-value pairs.
2. Cheap alternative global order ranked by repeated-value coverage.
3. Conditional prefix partition order for modest-size inputs.

The final comparison uses the actual serialized-row objective: the sum of LCPs
between lexicographically adjacent row strings.
"""

from collections import Counter, defaultdict
from typing import Dict, List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Data-preserving bounded optimizer for serialized prompt-prefix reuse."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe reference without mutating it."""
        self.df = df

    @staticmethod
    def _cell_string(value) -> str:
        """Return evaluator-compatible serialization for one dataframe cell."""
        if value is None:
            return ""
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute character LCP with binary-searched C-level slice equality."""
        limit = min(len(left), len(right))
        if limit == 0:
            return 0
        if left == right:
            return limit

        low, high = 0, limit
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    def _trie_score(self, strings: List[str]) -> int:
        """Return exact ideal Trie reuse from sorted adjacent serialized rows."""
        if len(strings) < 2:
            return 0

        strings.sort()
        total = 0
        previous = strings[0]
        for current in strings[1:]:
            total += self._lcp(previous, current)
            previous = current
        return total

    @staticmethod
    def _normalize_groups(col_merge) -> List[List]:
        """Normalize merge declarations while tolerating scalar malformed groups."""
        if not col_merge:
            return []

        groups = []
        for group in col_merge:
            if isinstance(group, (list, tuple)):
                if group:
                    groups.append(list(group))
            else:
                groups.append([group])
        return groups

    @staticmethod
    def _build_units(
        columns: List,
        col_merge,
        dependencies,
    ) -> Tuple[List[List[int]], Dict[int, set]]:
        """Create indivisible merge units and unit-level dependency edges."""
        positions_by_name = defaultdict(list)
        for position, name in enumerate(columns):
            positions_by_name[name].append(position)

        units = []
        used = set()

        for group in Evolved._normalize_groups(col_merge):
            positions = []
            for name in group:
                for position in positions_by_name.get(name, []):
                    if position not in used:
                        used.add(position)
                        positions.append(position)
            if positions:
                units.append(positions)

        for position in range(len(columns)):
            if position not in used:
                units.append([position])

        position_to_unit = {}
        for unit_id, unit in enumerate(units):
            for position in unit:
                position_to_unit[position] = unit_id

        predecessors = {unit_id: set() for unit_id in range(len(units))}
        for pair in dependencies or []:
            if not isinstance(pair, (tuple, list)) or len(pair) < 2:
                continue

            before, after = pair[0], pair[1]
            for left_position in positions_by_name.get(before, []):
                for right_position in positions_by_name.get(after, []):
                    left_unit = position_to_unit[left_position]
                    right_unit = position_to_unit[right_position]
                    if left_unit != right_unit:
                        predecessors[right_unit].add(left_unit)

        return units, predecessors

    @staticmethod
    def _topological_order(
        unit_count: int,
        predecessors: Dict[int, set],
        priority: List[int],
    ) -> List[int]:
        """Return a deterministic dependency-respecting order near priority."""
        rank = {unit: index for index, unit in enumerate(priority)}
        remaining = set(range(unit_count))
        completed = set()
        result = []

        while remaining:
            available = [
                unit
                for unit in remaining
                if predecessors.get(unit, set()).issubset(completed)
            ]

            if not available:
                # Preserve deterministic behavior even with cyclic declarations.
                available = list(remaining)

            chosen = min(
                available,
                key=lambda unit: (rank.get(unit, unit_count), unit),
            )
            result.append(chosen)
            completed.add(chosen)
            remaining.remove(chosen)

        return result

    @staticmethod
    def _factorize(values: List[str]) -> Tuple[List[int], List[int], List[int]]:
        """Factorize strings into row codes, unique lengths, and frequencies."""
        mapping = {}
        codes = []
        lengths = []
        counts = []

        for value in values:
            code = mapping.get(value)
            if code is None:
                code = len(lengths)
                mapping[value] = code
                lengths.append(len(value))
                counts.append(0)

            codes.append(code)
            counts[code] += 1

        return codes, lengths, counts

    @staticmethod
    def _pair_score(lengths: List[int], counts: List[int]) -> int:
        """Score a unit by length-weighted repeated-value pairs."""
        return sum(
            length * count * (count - 1)
            for length, count in zip(lengths, counts)
            if length and count > 1
        )

    @staticmethod
    def _coverage_score(lengths: List[int], counts: List[int]) -> int:
        """Score a unit by repeated-value coverage rather than pair count."""
        return sum(
            length * (count - 1)
            for length, count in zip(lengths, counts)
            if length and count > 1
        )

    @staticmethod
    def _serialize_global(
        unit_values: List[List[str]],
        order: List[int],
        n_rows: int,
    ) -> List[str]:
        """Serialize all rows using one common unit ordering."""
        return [
            "".join(unit_values[unit][row] for unit in order)
            for row in range(n_rows)
        ]

    @staticmethod
    def _serialize_orders(
        unit_values: List[List[str]],
        orders: List[List[int]],
    ) -> List[str]:
        """Serialize all rows using potentially row-specific unit orderings."""
        return [
            "".join(unit_values[unit][row] for unit in orders[row])
            for row in range(len(orders))
        ]

    def _conditional_candidate(
        self,
        codes_by_unit: List[List[int]],
        lengths_by_unit: List[List[int]],
        global_order: List[int],
        predecessors: Dict[int, set],
        col_stop,
        early_stop,
    ) -> List[List[int]]:
        """Build a shallow conditional prefix partition tree plus global tails."""
        unit_count = len(codes_by_unit)
        n_rows = len(codes_by_unit[0]) if unit_count else 0
        orders = [[] for _ in range(n_rows)]

        if not unit_count or not n_rows:
            return orders

        candidate_set = set(global_order[:min(12, unit_count)])

        # Include predecessors so candidate prefixes can remain dependency legal.
        changed = True
        while changed:
            changed = False
            for unit in tuple(candidate_set):
                for predecessor in predecessors.get(unit, set()):
                    if predecessor not in candidate_set:
                        candidate_set.add(predecessor)
                        changed = True

        candidates = [unit for unit in global_order if unit in candidate_set]
        max_depth = min(4, len(candidates))

        try:
            if col_stop is not None and int(col_stop) > 0:
                max_depth = min(max_depth, int(col_stop))
        except Exception:
            pass

        try:
            minimum_score = max(0, int(early_stop or 0))
        except Exception:
            minimum_score = 0

        groups = [(list(range(n_rows)), frozenset())]

        for _ in range(max_depth):
            next_groups = []
            progressed = False

            for rows, completed in groups:
                if len(rows) < 2:
                    next_groups.append((rows, completed))
                    continue

                available = [
                    unit
                    for unit in candidates
                    if unit not in completed
                    and predecessors.get(unit, set()).issubset(completed)
                ]

                if not available:
                    next_groups.append((rows, completed))
                    continue

                best_unit = None
                best_score = 0

                for unit in available:
                    counts = Counter(codes_by_unit[unit][row] for row in rows)
                    lengths = lengths_by_unit[unit]
                    score = sum(
                        lengths[code] * count * (count - 1)
                        for code, count in counts.items()
                        if count > 1 and lengths[code]
                    )

                    if (
                        score > best_score
                        or (
                            score == best_score
                            and best_unit is not None
                            and unit < best_unit
                        )
                    ):
                        best_score = score
                        best_unit = unit

                if best_unit is None or best_score <= minimum_score:
                    next_groups.append((rows, completed))
                    continue

                progressed = True
                codes = codes_by_unit[best_unit]

                for row in rows:
                    orders[row].append(best_unit)

                partitions = defaultdict(list)
                for row in rows:
                    partitions[codes[row]].append(row)

                updated = frozenset(set(completed) | {best_unit})
                for partition in partitions.values():
                    next_groups.append((partition, updated))

            groups = next_groups
            if not progressed:
                break

        for row, prefix in enumerate(orders):
            used = set(prefix)
            prefix.extend(unit for unit in global_order if unit not in used)

        return orders

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge: List[List[str]] = [],
        one_way_dep: List[Tuple[str, str]] = [],
        distinct_value_threshold: float = 0.8,
        parallel: bool = True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Return the highest-scoring bounded data-preserving column permutation."""
        n_rows, n_cols = df.shape
        columns = list(df.columns)

        if n_rows == 0 or n_cols == 0:
            return df.copy(), [columns[:] for _ in range(n_rows)]

        raw_values = df.to_numpy(dtype=object, copy=False)
        units, predecessors = self._build_units(columns, col_merge, one_way_dep)

        cell_strings = [
            [self._cell_string(raw_values[row, col]) for row in range(n_rows)]
            for col in range(n_cols)
        ]

        unit_values = []
        codes_by_unit = []
        lengths_by_unit = []
        pair_scores = []
        coverage_scores = []

        for unit in units:
            if len(unit) == 1:
                values = cell_strings[unit[0]]
            else:
                values = [
                    "".join(cell_strings[column][row] for column in unit)
                    for row in range(n_rows)
                ]

            codes, lengths, counts = self._factorize(values)
            unit_values.append(values)
            codes_by_unit.append(codes)
            lengths_by_unit.append(lengths)
            pair_scores.append(self._pair_score(lengths, counts))
            coverage_scores.append(self._coverage_score(lengths, counts))

        pair_priority = sorted(
            range(len(units)),
            key=lambda unit: (-pair_scores[unit], unit),
        )
        global_order = self._topological_order(
            len(units),
            predecessors,
            pair_priority,
        )

        candidates = [global_order]

        # The alternate ranking is cheap to construct.  Restrict its full Trie
        # evaluation to modest inputs so it cannot create runtime regressions.
        use_alternate = (
            len(units) >= 2
            and n_rows >= 2
            and n_rows * len(units) <= 90000
        )

        if use_alternate:
            coverage_priority = sorted(
                range(len(units)),
                key=lambda unit: (-coverage_scores[unit], -pair_scores[unit], unit),
            )
            coverage_order = self._topological_order(
                len(units),
                predecessors,
                coverage_priority,
            )
            if coverage_order != global_order:
                candidates.append(coverage_order)

        use_conditional = (
            n_rows >= 2
            and len(units) >= 2
            and n_rows <= 30000
            and n_rows * len(units) <= 180000
        )

        conditional_orders = None
        if use_conditional:
            conditional_orders = self._conditional_candidate(
                codes_by_unit,
                lengths_by_unit,
                global_order,
                predecessors,
                col_stop,
                early_stop,
            )

        best_global_order = global_order
        best_orders = None
        best_score = -1

        for order in candidates:
            score = self._trie_score(
                self._serialize_global(unit_values, order, n_rows)
            )
            if score > best_score:
                best_score = score
                best_global_order = order
                best_orders = None

        if conditional_orders is not None:
            conditional_score = self._trie_score(
                self._serialize_orders(unit_values, conditional_orders)
            )
            if conditional_score > best_score:
                best_score = conditional_score
                best_orders = conditional_orders

        if best_orders is None:
            positions = [
                position
                for unit in best_global_order
                for position in units[unit]
            ]
            output = raw_values[:, positions].copy()
            ordering = [columns[position] for position in positions]
            column_orderings = [ordering[:] for _ in range(n_rows)]
        else:
            output = np.empty((n_rows, n_cols), dtype=object)
            column_orderings = []

            for row in range(n_rows):
                positions = [
                    position
                    for unit in best_orders[row]
                    for position in units[unit]
                ]
                output[row, :] = raw_values[row, positions]
                column_orderings.append(
                    [columns[position] for position in positions]
                )

        reordered = pd.DataFrame(
            output,
            index=df.index.copy(),
            columns=df.columns.copy(),
            dtype=object,
        )
        return reordered, column_orderings


